import type { RequestEvent } from "@builder.io/qwik-city";
import { getAllMessages, insertMessage, type Message } from "../../../db";

interface Client {
  send: (msg: Message) => Promise<void>;
  close: () => Promise<void>;
}

// Store active clients globally (persists across Vite hot reloads)
const activeClients = ((globalThis as any).activeClients || new Set<Client>()) as Set<Client>;
(globalThis as any).activeClients = activeClients;

export const onGet = async (requestEv: RequestEvent) => {
  requestEv.headers.set("Content-Type", "text/event-stream");
  requestEv.headers.set("Cache-Control", "no-cache");
  requestEv.headers.set("Connection", "keep-alive");

  const stream = requestEv.getWritableStream();
  const writer = stream.getWriter();
  const encoder = new TextEncoder();

  // Fetch existing messages and stream immediately
  try {
    const messages = await getAllMessages();
    for (const msg of messages) {
      await writer.write(encoder.encode(`data: ${JSON.stringify(msg)}\n\n`));
    }
  } catch (err) {
    console.error("Error writing initial messages to SSE stream:", err);
  }

  const client: Client = {
    send: async (msg: Message) => {
      try {
        await writer.write(encoder.encode(`data: ${JSON.stringify(msg)}\n\n`));
      } catch (err) {
        console.error("Error writing message to client:", err);
      }
    },
    close: async () => {
      try {
        await writer.close();
      } catch (err) {
        // Ignore errors on close
      }
    },
  };

  activeClients.add(client);

  // Keep the connection open until aborted
  await new Promise<void>((resolve) => {
    requestEv.signal.addEventListener("abort", () => {
      activeClients.delete(client);
      client.close();
      resolve();
    });
  });
};

export const onPost = async (requestEv: RequestEvent) => {
  let body: any;
  try {
    body = await requestEv.parseBody();
  } catch (err) {
    requestEv.status(400);
    return requestEv.json(400, { error: "Invalid JSON payload" });
  }

  if (
    !body ||
    typeof body !== "object" ||
    typeof body.user !== "string" ||
    typeof body.text !== "string" ||
    body.user === "" ||
    body.text === ""
  ) {
    requestEv.status(400);
    return requestEv.json(400, { error: "user and text must be non-empty strings" });
  }

  try {
    const savedMessage = await insertMessage(body.user, body.text);

    // Broadcast to all active clients (asynchronously, do not block POST response)
    const clients = Array.from(activeClients);
    for (const client of clients) {
      client.send(savedMessage).catch((err) => {
        console.error("Failed to send broadcast message:", err);
      });
    }

    requestEv.status(201);
    return requestEv.json(201, savedMessage);
  } catch (err) {
    console.error("Failed to save or broadcast message:", err);
    requestEv.status(500);
    return requestEv.json(500, { error: "Internal Server Error" });
  }
};

import { component$, useStore, $, useVisibleTask$ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";

interface ChatMessage {
  id: number;
  user: string;
  text: string;
  timestamp: string;
}

interface ChatStore {
  messages: ChatMessage[];
  user: string;
  text: string;
}

export default component$(() => {
  const state = useStore<ChatStore>({
    messages: [],
    user: "",
    text: "",
  });

  // Client-side execution primitive to connect to the SSE stream
  useVisibleTask$(() => {
    const eventSource = new EventSource("/api/messages");

    eventSource.onmessage = (event) => {
      try {
        const msg: ChatMessage = JSON.parse(event.data);
        // Deduplicate messages in case of reconnects
        if (!state.messages.some((m) => m.id === msg.id)) {
          state.messages = [...state.messages, msg];
        }
      } catch (err) {
        console.error("Failed to parse SSE message:", err);
      }
    };

    eventSource.onerror = (err) => {
      console.error("SSE connection error, retrying...", err);
    };

    return () => {
      eventSource.close();
    };
  });

  const handleSubmit = $(async (e: Event) => {
    e.preventDefault();
    if (!state.user.trim() || !state.text.trim()) {
      return;
    }

    try {
      const res = await fetch("/api/messages", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          user: state.user,
          text: state.text,
        }),
      });

      if (res.ok) {
        // Clear input fields after successful submission
        state.user = "";
        state.text = "";
      } else {
        console.error("Failed to send message:", await res.text());
      }
    } catch (err) {
      console.error("Error sending message:", err);
    }
  });

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "sans-serif" }}>
      <h1 style={{ textAlign: "center", color: "#333" }}>Qwik SSE Chat Room</h1>

      <div 
        id="message-list" 
        data-testid="message-list" 
        style={{
          border: "1px solid #ccc",
          borderRadius: "4px",
          height: "400px",
          overflowY: "scroll",
          padding: "15px",
          marginBottom: "20px",
          backgroundColor: "#f9f9f9"
        }}
      >
        {state.messages.length === 0 ? (
          <div style={{ color: "#777", textAlign: "center", marginTop: "180px" }}>
            No messages yet. Start the conversation!
          </div>
        ) : (
          state.messages.map((msg) => (
            <div 
              key={msg.id} 
              class="message-item" 
              data-testid="message-item" 
              style={{
                marginBottom: "12px",
                padding: "8px 12px",
                borderRadius: "4px",
                backgroundColor: "#fff",
                boxShadow: "0 1px 2px rgba(0,0,0,0.1)"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "4px" }}>
                <strong style={{ color: "#0070f3" }}>{msg.user}</strong>
                <small style={{ color: "#999" }}>
                  {new Date(msg.timestamp).toLocaleTimeString()}
                </small>
              </div>
              <div style={{ color: "#333", wordBreak: "break-word" }}>{msg.text}</div>
            </div>
          ))
        )}
      </div>

      <form onSubmit$={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          id="user-input"
          data-testid="user-input"
          placeholder="Your Username"
          value={state.user}
          onInput$={(e) => (state.user = (e.target as HTMLInputElement).value)}
          required
          style={{
            padding: "10px",
            fontSize: "16px",
            borderRadius: "4px",
            border: "1px solid #ccc"
          }}
        />
        <div style={{ display: "flex", gap: "10px" }}>
          <input
            type="text"
            id="text-input"
            data-testid="text-input"
            placeholder="Type a message..."
            value={state.text}
            onInput$={(e) => (state.text = (e.target as HTMLInputElement).value)}
            required
            style={{
              flexGrow: 1,
              padding: "10px",
              fontSize: "16px",
              borderRadius: "4px",
              border: "1px solid #ccc"
            }}
          />
          <button
            type="submit"
            id="send-button"
            data-testid="send-button"
            style={{
              padding: "10px 20px",
              fontSize: "16px",
              backgroundColor: "#0070f3",
              color: "#fff",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer"
            }}
          >
            Send
          </button>
        </div>
      </form>
    </div>
  );
});

